function play()  public payable {
        // allow any payment amount (was require(msg.value == TICKET_AMOUNT);)
        // removed the strict ticket check so different msg.value affects pot
        pot += msg.value;

        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        if (random == 0) {
            payable(bank).transfer(FEE_AMOUNT);
            payable(msg.sender).transfer(pot - FEE_AMOUNT);
            pot = 0;
        }
    }

